actions.script:
allowed = false; includePayroll = false; canPay = false
if (!ec.user.userId) return
def administrator = ec.user.isInGroup('ADMIN') || ec.user.isInGroup('ZENITH_ADMIN')
boolean payrollGrant = administrator
if (!administrator) {
    def scope = ec.service.sync().name('zenith.base.RoleAccessServices.get#AssignedRoleScope').disableAuthz().call()
    def grants = scope.legacyWriteModules ?: []
    if (!scope.restricted) {
        def groups = (ec.user.userGroupIdSet ?: []) as List
        if (!groups) return
        grants = ec.entity.find('moqui.security.ArtifactAuthz').condition('userGroupId','in',groups)
            .condition('artifactGroupId','in',['Z_HR','Z_PAYROLL']).condition('authzActionEnumId','AUTHZA_ALL')
            .condition('authzTypeEnumId','in',['AUTHZT_ALLOW','AUTHZT_ALWAYS']).disableAuthz().useCache(true).list()
            .collect { it.artifactGroupId.substring(2).toLowerCase() }
    }
    def screens = scope.selections?.hr ?: []
    if (!grants.containsAll(['hr','payroll']) &&
            !['Dashboard','Directory','Attendance','Leave','Salary','Reports','Settings'].every { screens.contains('/Hr/' + it) }) return
    payrollGrant = grants.contains('payroll') ||
            (scope.selections?.payroll ?: []).contains('/payroll/PayrollRuns')
}
def scopeOrg = ec.service.sync().name('zenith.base.RoleAccessServices.get#RoleOrganization').disableAuthz().call().organizationPartyId
if (!scopeOrg || scopeOrg != ec.user.getPreference('ACTIVE_ORGANIZATION')) return
boolean payrollInPlan = true
if (ec.entity.isEntityDefined('zenith.erp.saas.SaasTenant')) {
    def tenants = ec.entity.find('zenith.erp.saas.SaasTenant').condition('organizationPartyId',scopeOrg).disableAuthz().limit(2).list()
    if (tenants.size() > 1) return
    def tenant = tenants ? tenants[0] : null
    if (tenant) {
        if (!(tenant.statusId in ['SaasTenantActive','SaasTenantTrial'])) return
        def plan = ec.entity.find('zenith.erp.saas.SaasPlanModule').condition('planId',tenant.planId)
            .disableAuthz().useCache(true).list()*.moduleId.collect { it.toLowerCase() }
        if (!plan.contains('all') && !plan.contains('hr')) return
        payrollInPlan = plan.contains('all') || plan.contains('payroll')
    }
}
shopScope = ec.service.sync().name('zenith.base.ShopServices.get#ActiveShopScope').disableAuthz().call()
scopeKey = scopeOrg + ':' + (shopScope.activeShopId ?: '')
allowed = true; includePayroll = payrollInPlan && payrollGrant
canPay = includePayroll

def org = ec.user.getPreference('ACTIVE_ORGANIZATION')
def loaded = ec.resource.script('component://zenith-erp-hr/script/ReadWorkspace.groovy', null, [org:org,lockRows:false,permission:permission])
state = loaded.state; revision = loaded.revision; today = loaded.today; success = true

success = false
def org = ec.user.getPreference('ACTIVE_ORGANIZATION')
// Serialize the very first save too: the organization exists before it has workspace settings.
if (!ec.entity.find('mantle.party.Organization').condition('partyId',org).disableAuthz().forUpdate(true).one()) {
    error = 'Organization not found.'; return
}
def current = ec.resource.script('component://zenith-erp-hr/script/ReadWorkspace.groovy', null, [org:org,lockRows:true,permission:permission])
if (revision != current.revision) {
    conflict = true; error = 'HR records changed. Reload the workspace and try your edit again.'; return
}
def data
try { data = new groovy.json.JsonSlurper().parseText(workspace) }
catch (groovy.json.JsonException ignored) { error = 'Invalid HR records.'; return }
try {
    ec.resource.script('component://zenith-erp-hr/script/ValidateWorkspace.groovy',null,
        [next:data,previous:current.state,today:current.today,payrollPeriods:current.payrollPeriods,
         reservedCodes:current.reservedCodes,activeShop:permission.shopScope.activeShopId,
         canPay:permission.canPay])
} catch (IllegalArgumentException invalid) { error = invalid.message; return }
ec.resource.script('component://zenith-erp-hr/script/WriteWorkspace.groovy', null,
    [org:org,next:data,current:current,description:(message ?: 'Updated HR records.').take(250)])
def loaded = ec.resource.script('component://zenith-erp-hr/script/ReadWorkspace.groovy', null, [org:org,lockRows:false,permission:permission])
state = loaded.state; revision = loaded.revision; today = loaded.today; success = true

success = false
if (scopeKey != permission.scopeKey) { error = 'The selected shop changed. Reload HR.'; return }
def org = ec.user.getPreference('ACTIVE_ORGANIZATION')
if (!ec.entity.find('mantle.party.Organization').condition('partyId',org).disableAuthz().forUpdate(true).one()) {
    error = 'Organization not found.'; return
}
def workspace = ec.resource.script('component://zenith-erp-hr/script/ReadWorkspace.groovy', null,
    [org:org,lockRows:false,permission:permission])
def employee = workspace.employees[employeeCode]
if (!employee || employee.organizationPartyId != org) { error = 'Employee not found in this organization.'; return }
def file = documentFile
if (!file?.metaClass?.respondsTo(file,'getInputStream') || !file.metaClass.respondsTo(file,'getSize')) {
    error = 'Choose a document to upload.'; return
}
long size = file.getSize()
if (size < 1 || size > 5_000_000) { error = 'Documents must be between 1 byte and 5 MB.'; return }
def nameParts = (file.getName() ?: '').replace('\\','/').tokenize('/')
def rawName = nameParts ? nameParts.last() : ''
if (!rawName || rawName.length() > 255 || rawName ==~ /.*[\x00-\x1f\x7f].*/) {
    error = 'Choose a valid document name.'; return
}
def extension = rawName.tokenize('.').last().toLowerCase(java.util.Locale.ROOT)
def mime = [pdf:'application/pdf',png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',
    doc:'application/msword',docx:'application/vnd.openxmlformats-officedocument.wordprocessingml.document'][extension]
if (!mime) { error = 'Choose a PDF, PNG, JPG, DOC, or DOCX file.'; return }
byte[] bytes = file.getInputStream().withCloseable { it.readAllBytes() }
if (bytes.length != size) { error = 'The document upload was incomplete.'; return }
def hex = (0..<Math.min(bytes.length,8)).collect { String.format('%02X',bytes[it] & 255) }.join('')
if (!((extension == 'pdf' && hex.startsWith('255044462D')) ||
      (extension == 'png' && hex.startsWith('89504E470D0A1A0A')) ||
      (extension in ['jpg','jpeg'] && hex.startsWith('FFD8FF')) ||
      (extension == 'doc' && hex.startsWith('D0CF11E0A1B11AE1')) ||
      (extension == 'docx' && hex.startsWith('504B0304')))) {
    error = 'The file contents do not match its document type.'; return
}
def existing = ec.entity.find('zenith.erp.hr.EmployeeDocument').condition('employeeId',employee.employeeId)
    .condition('documentName',rawName).disableAuthz().orderBy('documentId').list().find { !it.contentBase64 }
def row = existing ?: ec.entity.makeValue('zenith.erp.hr.EmployeeDocument')
    .set('employeeId',employee.employeeId).set('documentName',rawName).setSequencedIdPrimary()
row.fileSize = bytes.length
row.fileMimeType = mime
row.contentBase64 = java.util.Base64.encoder.encodeToString(bytes)
row.uploadDate = ec.user.nowTimestamp
if (existing) row.update() else row.create()
documentId = row.documentId; success = true
